import os, stat, time, datetime, zlib
from dataclasses import dataclass, field

MAGIC7 = b"7z\xbc\xaf'\x1c"
EPOCH = 116444736000000000

class ArchiveError(Exception):
    def __init__(self, message='Is not archive', kind=None):
        self.message, self.kind = message, kind
        super().__init__(message)

@dataclass
class Entry:
    name: str = ''
    data: bytes = b''
    size: object = 0
    packed: object = 0
    mtime: object = None
    ctime: object = None
    atime: object = None
    mode: object = None
    attr: object = None
    crc: object = None
    method: str = ''
    block: object = None
    directory: bool = False
    encrypted: bool = False
    link: str = ''
    source: str = ''
    props: dict = field(default_factory=dict)

    def logname(self):
        return self.name.rstrip('/') + ('/' if self.directory else '')

@dataclass
class Archive:
    typ: str
    entries: list = field(default_factory=list)
    props: dict = field(default_factory=dict)
    physical: int = 0
    raw: bytes = b''
    errors: list = field(default_factory=list)
    offset: int = 0
    warning: str = ''


def crc32(b): return zlib.crc32(b) & 0xffffffff

def numstr(n): return '' if n is None else str(n)

def crcstr(n): return '' if n is None else f'{n:08X}'

def ticks(ns): return ns // 100 + EPOCH

def ns_from_ticks(t): return (t - EPOCH) * 100

def datefmt(ns, precision=0):
    if ns is None: return ''
    try:
        sec, frac = divmod(int(ns), 1000000000)
        v=time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(sec))
        if precision: v += '.' + str(frac).zfill(9)[:precision]
        return v
    except (ValueError,OverflowError,OSError): return ''

def sizefmt(size):
    v=f'{size} bytes'
    if size:
        units=[(1<<40,'TiB'),(1<<30,'GiB'),(1<<20,'MiB'),(1<<10,'KiB')]
        for x,s in units:
            if size >= x or x==1024:
                v+=f' ({(size+x-1)//x} {s})'; break
    return v

def counts(entries, unknown=False):
    nd=sum(e.directory for e in entries); nf=len(entries)-nd
    n=sum((e.size or 0) for e in entries if not e.directory)
    return countfmt(nd,nf,n,unknown)

def countfmt(nd,nf,n,unknown=False):
    v=[]
    if nd: v.append(f'{nd} '+('folder' if nd==1 else 'folders'))
    v.append(f'{nf} '+('file' if nf==1 else 'files'))
    if not unknown: v.append(sizefmt(n))
    return ', '.join(v)

def modefmt(e):
    if e.mode is None: return ''
    return stat.filemode(e.mode)

def attrfmt(e, typ='7z'):
    if e.attr is None and e.mode is None: return ''
    a=e.attr or 0
    letters=''
    if e.directory or a & 0x10: letters+='D'
    if a & 1: letters+='R'
    if a & 2: letters+='H'
    if a & 4: letters+='S'
    if typ!='zip' and a & 0x20: letters+='A'
    m=modefmt(e)
    return letters+(' '+m if m else '')

def shortattr(e,typ='7z'):
    a=e.attr or 0
    return ''.join(['D' if e.directory else '.', 'R' if a & 1 else '.', 'H' if a & 2 else '.', 'S' if a & 4 else '.', 'A' if a & 32 and typ!='zip' else '.'])
