"""LZMA range stream finalization for length-delimited containers.

The system encoder writes an end marker. This transcodes the range symbols
up to the given uncompressed length and finalizes that stream without one.
"""
import lzma

class RangeCopy:
    def __init__(self, data):
        self.data=data; self.pos=5
        self.code=int.from_bytes(data[1:5],'big'); self.rng=0xffffffff
        self.low=0; self.erng=0xffffffff; self.cache=0; self.pending=1
        self.out=bytearray(); self.probs={}
    def shift(self):
        lo=self.low & 0xffffffff; hi=self.low >> 32
        if lo < 0xff000000 or hi:
            self.out.append((self.cache + hi) & 255)
            if self.pending>1: self.out.extend(bytes([(255+hi)&255])*(self.pending-1))
            self.cache=(lo>>24)&255; self.pending=0
        self.pending+=1; self.low=(lo & 0xffffff)<<8
    def normalize(self):
        if self.rng < (1<<24):
            self.rng <<= 8
            self.code=((self.code << 8) | (self.data[self.pos] if self.pos < len(self.data) else 0)) & 0xffffffff
            self.pos+=1
        if self.erng < (1<<24):
            self.erng <<= 8; self.shift()
    def bit(self,key):
        p=self.probs.get(key,1024)
        bound=(self.rng>>11)*p; eb=(self.erng>>11)*p
        if self.code < bound:
            b=0; self.rng=bound; self.erng=eb; p+=(2048-p)>>5
        else:
            b=1; self.code-=bound; self.rng-=bound
            self.low+=eb; self.erng-=eb; p-=p>>5
        self.probs[key]=p
        self.normalize(); return b
    def direct(self,n):
        v=0
        for _ in range(n):
            self.rng >>= 1; self.erng >>= 1
            b=int(self.code>=self.rng)
            if b: self.code-=self.rng; self.low+=self.erng
            v=(v<<1)|b; self.normalize()
        return v
    def tree(self,key,n,reverse=False,start=0):
        s=1; v=0
        for i in range(n):
            b=self.bit((key,start+s)); s=(s<<1)|b
            v |= b<<i
        return v if reverse else s-(1<<n)
    def length(self,key,pos):
        if not self.bit((key,'choice',0)): return self.tree((key,'lo',pos),3)
        if not self.bit((key,'choice',1)): return 8+self.tree((key,'mid',pos),3)
        return 16+self.tree((key,'hi'),8)
    def finish(self):
        for _ in range(5): self.shift()
        return bytes(self.out)

def without_eos(raw,size,lc=3,lp=0,pb=2):
    c=RangeCopy(raw); result=bytearray(); state=0; reps=[0,0,0,0]
    while len(result)<size:
        pos=len(result); ps=pos & ((1<<pb)-1)
        if c.bit(('match',state,ps))==0:
            prev=result[-1] if result else 0
            ctx=((pos & ((1<<lp)-1))<<lc)+(prev>>(8-lc)); sym=1
            if state>=7:
                mb=result[-reps[0]-1]
                while sym<256:
                    m=(mb>>7)&1; mb=(mb<<1)&255
                    b=c.bit(('lit',ctx,((1+m)<<8)+sym));sym=(sym<<1)|b
                    if b!=m: break
            while sym<256: sym=(sym<<1)|c.bit(('lit',ctx,sym))
            result.append(sym-256)
            state=0 if state<4 else state-3 if state<10 else state-6
            continue
        if c.bit(('rep',state)):
            short=False
            if not c.bit(('g0',state)):
                if not c.bit(('r0long',state,ps)):
                    state=9 if state<7 else 11; length=1; short=True
            else:
                if not c.bit(('g1',state)): i=1
                elif not c.bit(('g2',state)): i=2
                else: i=3
                d=reps.pop(i); reps.insert(0,d)
            if not short:
                length=c.length('rlen',ps)+2;state=8 if state<7 else 11
        else:
            length=c.length('len',ps)+2;state=7 if state<7 else 10
            slot=c.tree(('slot',min(length-2,3)),6)
            if slot<4: dist=slot
            else:
                bits=(slot>>1)-1; dist=(2|(slot&1))<<bits
                if slot<14: dist+=c.tree('dist',bits,True,dist-slot-1)
                else:
                    dist+=c.direct(bits-4)<<4
                    dist+=c.tree('align',4,True)
            if dist==0xffffffff: break
            reps.insert(0,dist);reps.pop()
        for _ in range(length): result.append(result[-reps[0]-1])
    if len(result)!=size: raise ValueError('LZMA size mismatch')
    return c.finish()

def encode(data, dic=4096, level=5, lc=3,lp=0,pb=2, nice=32,header=False):
    opts={'id':lzma.FILTER_LZMA1,'dict_size':dic,'lc':lc,'lp':lp,'pb':pb,
          'mode':lzma.MODE_NORMAL if level>=4 or header else lzma.MODE_FAST,
          'mf':lzma.MF_BT4 if level>=4 or header else lzma.MF_HC4,
          'nice_len':nice}
    raw=lzma.compress(data,format=lzma.FORMAT_RAW,filters=[opts])
    return without_eos(raw,len(data),lc,lp,pb)
