import os,re,stat
from .common import *


def haswild(p):return '*' in p or '?' in p

def matchpart(n,p,sensitive=True,wild=True):
    if not sensitive:n=n.lower();p=p.lower()
    if not wild:return n==p
    rx=''.join('.*' if c=='*' else '.' if c=='?' else re.escape(c) for c in p)
    return re.fullmatch(rx,n,re.S) is not None

def match(path,pattern,recurse=False,sensitive=True,wild=True,children=True):
    path=path.replace('\\','/').strip('/');pattern=pattern.replace('\\','/').strip('/')
    while pattern.startswith('./'):pattern=pattern[2:]
    pp=pattern.split('/');nn=path.split('/')
    starts=range(max(1,len(nn)-len(pp)+1)) if recurse else [0]
    for start in starts:
        if start+len(pp)>len(nn):continue
        if all(matchpart(a,b,sensitive,wild) for a,b in zip(nn[start:start+len(pp)],pp)):
            if children or start+len(pp)==len(nn):return True
    return False

def selected(name,o):
    pats=[(p,o.recursive(p)) for p in o.files if not p.startswith('@')]+o.includes
    if not pats:pats=[('*',False)]
    return any(match(name,p,r,o.sensitive,not o.spd) for p,r in pats) and not any(match(name,p,r,o.sensitive,not o.spd) for p,r in o.excludes)

def disk_entry(path,name,o,read=True):
    st=os.lstat(path) if o.snl else os.stat(path)
    isdir=stat.S_ISDIR(st.st_mode);link='';data=b''
    if stat.S_ISLNK(st.st_mode):
        link=os.readlink(path);data=link.encode()
    elif not isdir and read:
        with open(path,'rb') as f:data=f.read()
    e=Entry(name=name.rstrip('/'),data=data,size=0 if isdir else len(data) if read else st.st_size,mtime=st.st_mtime_ns,atime=st.st_atime_ns,ctime=getattr(st,'st_birthtime_ns',None),mode=st.st_mode,directory=isdir,link=link,source=path)
    e.attr=(st.st_mode<<16)|0x8000|(16 if isdir else 32)
    if not st.st_mode & stat.S_IWUSR:e.attr|=1
    return e

def scan(o,archivepath=None,read=True):
    entries=[];warnings=[];seen=set();dirs=set();archiveabs=os.path.abspath(archivepath) if archivepath else ''
    def excluded(name):return any(match(name,p,r,o.sensitive,not o.spd) for p,r in o.excludes)
    def add(path,name,descend=True):
        if not name or name=='.':
            walk(path,'');return
        if excluded(name):return
        if os.path.abspath(path)==archiveabs:return
        key=os.path.normpath(path)
        try:
            st=os.lstat(path) if o.snl else os.stat(path)
            if stat.S_ISFIFO(st.st_mode) or stat.S_ISSOCK(st.st_mode):return
            if key not in seen:
                e=disk_entry(path,name,o,read);entries.append(e);seen.add(key)
            if descend and stat.S_ISDIR(st.st_mode):walk(path,name)
        except OSError as ex:
            if (path,ex.errno) not in warnings:warnings.append((path,ex.errno))
    def walk(path,prefix):
        real=os.path.realpath(path)
        if real in dirs:return
        dirs.add(real)
        try:sub=list(os.scandir(path))
        except OSError as ex:warnings.append((path,ex.errno));return
        for e in sub:
            name=(prefix+'/' if prefix else '')+e.name;add(e.path,name)
    patterns=[(p,o.recursive(p)) for p in o.files]+o.includes
    if not patterns:patterns=[('*',False)]
    for pat,recur in patterns:
        pat=pat.replace('\\','/')
        if pat in ('.','./'):
            walk('.','');continue
        absflag=pat.startswith('/') or pat.startswith('./') or '..' in pat.split('/')
        exact=not haswild(pat) or o.spd
        if exact and os.path.lexists(pat) and not (recur and not os.path.isdir(pat)):
            name=os.path.basename(os.path.normpath(pat)) if absflag and not o.spf else os.path.normpath(pat)
            add(pat,name);continue
        if exact and not recur:
            warnings.append((pat,2));continue
        parts=pat.split('/');wi=next((i for i,p in enumerate(parts) if haswild(p)),len(parts)-1)
        prefix='/'.join(parts[:wi]);start=prefix or '.'
        pattern='/'.join(parts[wi:])
        if not os.path.isdir(start):
            # Wildcards that match nothing aren't scan failures.
            continue
        def search(path,rel=''):
            try:items=list(os.scandir(path))
            except OSError:return
            for d in items:
                rname=(rel+'/' if rel else '')+d.name
                if absflag and not o.spf:name=rname
                else:name=(prefix.rstrip('/')+'/' if prefix else '')+rname
                isdir=d.is_dir(follow_symlinks=not o.snl)
                if match(rname,pattern,recur,o.sensitive,not o.spd,False):add(d.path,name)
                elif isdir and (recur or '/' in pattern):
                    if not excluded(name):search(d.path,rname)
        search(start)
    return entries,warnings
