        if e.early or not ui:sys.stderr.write('\n\nCommand Line Error:\n'+e.msg+'\n')
        else:ui.err('\n\nCommand Line Error:\n'+e.msg+'\n')
        return 7
    except KeyboardInterrupt:
        if ui:ui.err('\n\nBreak signaled\n')
        return 255
    except BrokenPipeError:return 0
    except MemoryError:
        if ui:ui.err('\n\nERROR: Can not allocate memory\n')
        return 8
    except Exception as exc:
        if os.environ.get('REARCH_DEBUG'):raise
        if ui:return system_error(ui, 'errno='+str(exc.errno)+' : '+os.strerror(exc.errno) if isinstance(exc,OSError) else 'E_FAIL : Unspecified error')
