def read_bz_block(r):
    crc=r.get(32);random=r.get(1);orig=r.get(24);mask=r.get(16);used=[]
    for i in range(16):
        if mask & (1<<(15-i)):
            group=r.get(16)
            used.extend(i*16+j for j in range(16) if group & (1<<(15-j)))
    ng=r.get(3);ns=r.get(15);mtf=list(range(ng));sel=[]
    for i in range(ns):
        j=0
        while r.get(1):j+=1
        c=mtf.pop(j);mtf.insert(0,c);sel.append(c)
    lens=[]
    for i in range(ng):
        v=r.get(5);ll=[]
        for _ in range(len(used)+2):
            while r.get(1):v+=-1 if r.get(1) else 1
            ll.append(v)
        lens.append(ll)
    css=[codes(ll,True) for ll in lens]
    # Lookup tables avoid rebuilding maps for every symbol.
    maps=[{(n,v):j for j,(v,n) in enumerate(cs) if n} for cs in css]
    symbols=[];p=0
    while True:
        mp=maps[sel[p//50]];v=0
        for n in range(1,24):
            v=(v<<1)|r.get(1)
            if (n,v) in mp:break
        s=mp[n,v];symbols.append(s);p+=1
        if s==len(used)+1:break
    return crc,random,orig,used,symbols


def bz_tables(symbols,alpha,iterations=4):
    n=len(symbols);ng=2 if n<200 else 3 if n<600 else 4 if n<1200 else 5 if n<2400 else 6
    freq=[0]*alpha
    for s in symbols:freq[s]+=1
    lens=[[0]*alpha for _ in range(ng)];remaining=n;start=0
    for t in range(ng,0,-1):
        target=remaining//t;end=start;weight=0
        while weight<target and end<alpha:weight+=freq[end];end+=1
        end-=1
        if end>start and t!=ng and t!=1 and (ng-t)%2:
            weight-=freq[end];end-=1
        lens[t-1]=[0 if start<=v<=end else 15 for v in range(alpha)]
        start=end+1;remaining-=weight
    for _ in range(iterations):
        freqs=[[0]*alpha for _ in range(ng)];selectors=[]
